L("الفصل الثاني : الإخصاب عند قنفذ البحر", [36, 39],
  ["تعريف المشيج والإخصاب.", "التمييز بين الإخصاب الخارجي والداخلي.", "وصف مراحل الإخصاب عند قنفذ البحر."],
  "لماذا يُعد قنفذ البحر حيوانا مثاليا لدراسة الإخصاب؟",
  "الأمشاج خلايا جنسية تنتجها المناسل: الخصية (حيوانات منوية) والمبيض (بويضات). الإخصاب هو اندماج مشيج مذكر مع مشيج مؤنث لتكوين اللاقحة (الزيجوت) التي تنقسم انقسامات ميتوزية لتكوين فرد جديد. الإخصاب نوعان: خارجي يحدث في الماء، وداخلي يتم داخل جسم الأنثى. قنفذ البحر حيوان لافقاري من شوكيات الجلد منفصل الجنس، تسهل دراسة أمشاجه؛ بحقن كلوريد البوتاسيوم تُطلق الأمشاج. مراحل الإخصاب: تحرر الأمشاج في ماء البحر، انجذاب الحيوانات المنوية والتصاقها بالغشاء الجيلاتيني للبويضة، دخول حيوان منوي واحد فقط، ثم تنتفخ النواتان الذكرية والأنثوية وتتجه كل منهما نحو الأخرى وتندمجان (الاندماج النووي)، فتتكون اللاقحة التي تنقسم لتعطي جنينا ثم يرقة ثم قنفذ بحر جديدا.",
  ["الإخصاب: مشيج مذكر + مشيج مؤنث = لاقحة.", "خارجي (في الماء) وداخلي.", "يدخل حيوان منوي واحد فقط.", "اندماج النواتين: الإخصاب الحقيقي.", "اللاقحة ← جنين ← يرقة."],
  ("ما الخطوة التي تمثل الإخصاب بمفهومه الحقيقي؟", "اندماج النواتين الذكرية والأنثوية."),
  [S("مراحل الإخصاب عند قنفذ البحر", ["1) تحرر الأمشاج في الماء.", "2) انجذاب الحيوانات المنوية والتصاقها بالبويضة.", "3) دخول حيوان منوي واحد.", "4) انتفاخ النواتين واندماجهما.", "5) الانقسامات الميتوزية للاقحة."])],
  apps=[("أين يحدث الإخصاب الخارجي؟", "في الماء."), ("كيف نحصل على أمشاج قنفذ البحر في المختبر؟", "بحقنه بمحلول كلوريد البوتاسيوم.")]),
L("الفصل الثاني : فسيولوجية الإخصاب والخلط الكروموزومي", [39, 43],
  ["شرح الانجذاب الكيميائي وانفرادية الحيوان المنوي المخصب.", "وصف اليقظة الفسيولوجية للبويضة.", "شرح الخلط البيني والداخلي ودورهما في التنوع الوراثي."],
  "لماذا لا يشبه الإخوة بعضهم تماما رغم أنهم من نفس الأبوين؟",
  "بينت تجربة ليلي (1913) أن سائل البويضة يجذب الحيوانات المنوية وينشطها: هو الانجذاب الكيميائي؛ والمخصبات نوعية لا يؤثر مخصب نوع على الأنواع الأخرى. من بين آلاف الحيوانات المنوية ينجح واحد فقط في إخصاب البويضة (انفرادية الحيوان المنوي المخصب) بفضل تغيرات تحدث على سطحها. يسبب دخول الحيوان المنوي يقظة البويضة الفسيولوجية: تكوين غشاء الإخصاب وزيادة الشدة التنفسية (6 أضعاف عند قنفذ البحر). حياة الأمشاج قصيرة (البويضة لا تتجاوز 24 ساعة بعد الإباضة عند المرأة). يضمن الميوز الانتقال من الحالة الثنائية إلى الأحادية؛ وفي الطور الانفصالي الأول تتوزع الكروموزومات الأبوية والأمية عشوائيا (الخلط البيني) فيكون عدد التراكيب الممكنة 2ⁿ (n عدد الأزواج)، أي 2²³ = 8 388 608 نوعا من الأمشاج عند الإنسان؛ ويضيف العبور في الطور التمهيدي الأول خلطا داخليا. دورة قنفذ البحر ثنائية الصيغة: الخلايا الجسمية 2n والأمشاج n.",
  ["الانجذاب الكيميائي (تجربة ليلي).", "حيوان منوي واحد يخصب البويضة.", "اليقظة الفسيولوجية للبويضة.", "الخلط البيني: 2ⁿ تركيبا.", "العبور: خلط داخلي."],
  ("كم نوعا من الأمشاج يمكن أن ينتج الإنسان بالخلط البيني وحده؟", "2²³ = 8 388 608 نوعا."),
  [S("مدلول الإخصاب والميوز", ["الميوز: 2n ← n ؛ الإخصاب: n + n ← 2n.", "الخلط البيني: توزيع عشوائي للكروموزومات الأبوية والأمية (2ⁿ).", "الخلط الداخلي: العبور بين الكروماتيدات غير الشقيقة.", "(تصحيح: ص 41 كُتب «2³² = 8388608» والصواب 2²³ = 8 388 608 لأن للإنسان 23 زوجا.)"])],
  apps=[("ما مظاهر اليقظة الفسيولوجية للبويضة؟", "تكوين غشاء الإخصاب، زيادة الشدة التنفسية، تغير نفاذية الغشاء."), ("لماذا لا تخصب البويضة بحيوانين منويين؟", "لأن تغيرات سطحها بعد دخول الأول تمنع دخول غيره.")]),
L("ملحق : الخلية — تاريخ اكتشافها وطرق دراستها", [44, 57],
  ["تتبع تاريخ اكتشاف الخلية.", "معرفة مكونات المجهر الضوئي والمجهر الإلكتروني.", "مقارنة الخلية النباتية والحيوانية."],
  "كيف اكتُشفت الخلية رغم صغرها الشديد؟",
  "يُعد الهولندي زكرياء جانسن مكتشف المجهر المركب (1580)، ثم فحص فان ليفن هوك بعض الخلايا الحية، ثم رسم روبرت هوك قطاعات الفلين ووصفها بوحدات متجاورة سماها خلايا. أكد دوتروشي (1824) أن الخلية هي الوحدة الحقيقية لبناء الكائن الحي، وطور شلايدن (1838) وشوان (1839) هذه الفكرة: الخلية وحدة بناء النبات والحيوان. يتكون المجهر الضوئي من جهاز إضاءة (منبع ضوئي ومرآة) وجهاز عدسي (عدسة عينية وعدسة جسمية) ومنضدة وضوابط؛ قوة التكبير = تكبير العدسة العينية × تكبير الجسمية. صمم المجهر الإلكتروني انطلاقا من مبدأ دوبروي: يستعمل حزمة إلكترونات في أنبوب مفرغ من الهواء، ويكبر من 50 000 إلى 500 000 مرة، وقوة فصله (2 إلى 3 نانومتر) أكبر بألف مرة من المجهر الضوئي. الخلية النباتية لها جدار سليلوزي وبلاستيدات وفجوة كبيرة، والحيوانية لها جسم مركزي.",
  ["جانسن: المجهر المركب (1580).", "روبرت هوك: أول وصف للخلايا.", "شلايدن وشوان: نظرية الخلية.", "المجهر الضوئي: التكبير = عيني × جسمي.", "المجهر الإلكتروني: قوة فصل أكبر بألف مرة."],
  ("عدسة عينية ×20 وعدسة جسمية ×20: ما قوة التكبير؟", "20 × 20 = 400 مرة."),
  [S("مقارنة الخليتين", table=[["العنصر", "الخلية النباتية", "الخلية الحيوانية"], ["الجدار السليلوزي", "موجود", "غير موجود"], ["البلاستيدات", "موجودة", "غير موجودة"], ["الفجوة", "كبيرة", "صغيرة أو منعدمة"], ["الجسم المركزي", "غائب", "موجود"]]),
   S("تصحيح", ["(تصحيح: ص 44 ركّب روبرت هوك مجهره سنة 1665 لا «1965».)"])],
  apps=[("لماذا يحتاج المجهر الإلكتروني إلى أنبوب مفرغ من الهواء؟", "لأن الإلكترونات لا تسير في خط مستقيم إلا في الفراغ."), ("من أكد أن الخلية هي وحدة بناء الكائن الحي سنة 1824؟", "دوتروشي.")]),
L("ملحق : عضيات الخلية ووظائفها", [58, 67],
  ["وصف بنية الغشاء البلازمي (نموذج سينجر ونيكولسون).", "معرفة بنية ووظيفة الشبكة الأندوبلازمية وجهاز جولجي والميتوكندريا والبلاستيدات والمريكز."],
  "لماذا تسمى الميتوكندريا «بيوت الطاقة»؟",
  "يتكون الغشاء البلازمي، حسب نموذج سينجر ونيكولسون (1973)، من طبقة مزدوجة من الدهون المفسفرة (أقطاب محبة للماء وأخرى كارهة له) تتداخل معها بروتينات؛ ويتغير قوامه حسب الأحماض الدهنية (المشبعة تجعله صلبا، غير المشبعة تجعله مائعا). الشبكة الأندوبلازمية شبكة من الأنابيب والصهاريج المسطحة: حبيبية (تحمل الريبوزومات وتبني البروتينات) أو ملساء. جهاز جولجي مجموعة من أربعة إلى ثمانية كييسات مسطحة وحويصلات، يتدخل في تحويل البروتينات وإفرازها. الميتوكندريا عضية ذات غشاءين (الداخلي يكوّن أعرافا) بها ADN وريبوزومات خاصة؛ هي مقر التنفس الخلوي حيث تنتج الطاقة في شكل ATP، لذا تكثر في الألياف العضلية والحيوانات المنوية. البلاستيدات الخضراء مقر البناء الضوئي. المريكز يتكون من أسطوانتين متعامدتين من تسع مجموعات ثلاثية الأنابيب، يتضاعف ذاتيا ويولد المغزل والأهداب والأسواط. اللييفات (الميوزين والأكتين) وراء تقلص العضلات.",
  ["الغشاء: دهون مفسفرة + بروتينات (سينجر ونيكولسون).", "الشبكة الحبيبية: بناء البروتينات.", "جولجي: تحويل البروتينات وإفرازها.", "الميتوكندريا: التنفس وإنتاج ATP.", "المريكز: المغزل والأهداب والأسواط."],
  ("لماذا تكثر الميتوكندريا في الألياف العضلية؟", "لأنها تحتاج إلى طاقة كثيرة، والميتوكندريا تنتج ATP بالتنفس الخلوي."),
  [S("العضيات ووظائفها", table=[["العضية", "الوظيفة"], ["الشبكة الأندوبلازمية الحبيبية", "بناء البروتينات"], ["جهاز جولجي", "تحويل البروتينات وإفرازها"], ["الميتوكندريا", "التنفس الخلوي وإنتاج ATP"], ["البلاستيدة الخضراء", "البناء الضوئي"], ["المريكز", "تشكيل المغزل والأهداب والأسواط"]])],
  apps=[("ما مكونات الغشاء البلازمي؟", "طبقة مزدوجة من الدهون المفسفرة تتداخل معها بروتينات."), ("ما الفرق بين الشبكة الحبيبية والملساء؟", "الحبيبية تحمل الريبوزومات، والملساء خالية منها.")]),
L("ملحق : تكوين الأمشاج عند الإنسان", [68, 72],
  ["وصف مراحل تكوين الحيوانات المنوية.", "وصف تكوين البويضات وأوجه الاختلاف."],
  "كيف تتكون الحيوانات المنوية والبويضات؟",
  "يمر تكوين الحيوانات المنوية بأربع مراحل: 1) التضاعف: تتكاثر أمهات المني (2n) بانقسامات ميتوزية؛ 2) النمو: تزداد قليلا في الحجم وتصبح خلايا منوية ابتدائية (2n)؛ 3) النضج: الميوز، فتعطي الخلية المنوية الابتدائية خليتين ثانويتين (n) ثم أربع طلائع منوية (n)؛ 4) التحول: تتحول الطليعة المنوية إلى حيوان منوي بتكوين السوط من السنتريول، وتجمع حويصلات جولجي لتكوين القلنسوة، وتكاثف الكروماتين، وتجمع الميتوكندريا عند قاعدة السوط، والتخلص من معظم السيتوبلازم. يشبه تكوين البويضات تكوين الحيوانات المنوية (أمهات البيض ← بيضية ابتدائية ← ثانوية ← بويضة) لكنه يختلف في: زيادة كبيرة في الحجم أثناء النمو وتكوين المح (المواد الغذائية)، وانقسامات غير متساوية تعطي بويضة واحدة وكريات قطبية صغيرة، وغياب مرحلة التحول.",
  ["التضاعف ← النمو ← النضج (الميوز) ← التحول.", "خلية منوية ابتدائية ← 4 حيوانات منوية.", "البويضة: نمو كبير وتكوين المح.", "خلية بيضية ابتدائية ← بويضة واحدة + كريات قطبية."],
  ("ما الفرق في عدد الأمشاج الناتجة عن خلية أم مذكرة وأخرى مؤنثة؟", "الخلية المنوية الابتدائية تعطي 4 حيوانات منوية، والبيضية الابتدائية تعطي بويضة واحدة."),
  [S("مقارنة تكوين الأمشاج", table=[["المقارنة", "الحيوانات المنوية", "البويضات"], ["النمو", "طفيف", "كبير (تكوين المح)"], ["الانقسامات", "متساوية", "غير متساوية (كريات قطبية)"], ["مرحلة التحول", "موجودة", "غائبة"], ["عدد الأمشاج من خلية أم", "4", "1"]])],
  apps=[("ما مصدر سوط الحيوان المنوي؟", "السنتريول."), ("ما دور القلنسوة؟", "تحتوي على إنزيمات تساعد الحيوان المنوي على اختراق أغلفة البويضة.")]),
